// Generated by AI (UnitTest MCP)
use std::collections::HashSet;

use sha2::{Digest, Sha256};

use super::constitution::is_documentation_node;
use crate::controls::{forbid_change_control, forbid_change_observation, resolve_with_declared};
use crate::model::Consequence;
use crate::scope;
use crate::store::ConformanceAudit;
use crate::{
    now_unix, CodeBindingMode, ConformanceCheck, ConformanceEvidence, ConformanceResult, Goal,
    GoalStatus, GoverningClause, Lodestar, LodestarError, Result, Task, TaskStatus, Verdict,
};

const MAX_EVIDENCE_EVENTS: usize = 200;
const MAX_EVIDENCE_PROVENANCE: usize = 1_000;
const MAX_EVIDENCE_SUMMARY_BYTES: usize = 4_096;

/// The active clauses governing an intended or changed scope, bucketed by how
/// each relates to a covering task's own goal. Produced by
/// [`Lodestar::resolve_governing_clauses`] and consumed by both conformance and
/// `advise`; `(node_id, goal)` pairs preserve which node each clause governs.
#[derive(Debug, Default)]
pub(crate) struct GoverningClauses {
    /// Clauses that hard-lock a node against any change (`forbid_change`).
    pub forbid: Vec<(String, Goal)>,
    /// `governed` bindings to the covering task's own goal — the change is in scope.
    pub in_scope: Vec<(String, Goal)>,
    /// `governed` bindings to a different goal — a change here would drift.
    pub other: Vec<(String, Goal)>,
    /// Clauses governing an intended *procedural* action rather than a changed
    /// file (ADR-0034). Paired with the `workflow:` token they matched, which
    /// occupies the `node_id` slot when flattened — a workflow clause governs an
    /// action, and there is no code node to name.
    pub workflow: Vec<(String, Goal)>,
    /// Goals that were in scope only because the task declared coverage for them
    /// (ADR-0041). Non-empty means the verdict leaned on a declaration, which
    /// caps it at `needs_human`: an agent's own claim about its own breadth is
    /// reviewed, never self-certified.
    pub relied_on_coverage: Vec<String>,
}

impl GoverningClauses {
    /// Flatten the buckets into governing-clause rows (forbids first) — the shape
    /// surfaced by `advise` and by task pickup. Preserves which node each clause
    /// governs and its binding mode, so both callers read one representation.
    pub(crate) fn clauses(&self) -> Vec<GoverningClause> {
        let mut out = Vec::new();
        for (node, goal) in &self.forbid {
            out.push(GoverningClause {
                node_id: node.clone(),
                goal: goal.clone(),
                mode: CodeBindingMode::ForbidChange,
            });
        }
        for (node, goal) in self.in_scope.iter().chain(self.other.iter()) {
            out.push(GoverningClause {
                node_id: node.clone(),
                goal: goal.clone(),
                mode: CodeBindingMode::Governed,
            });
        }
        for (scope, goal) in &self.workflow {
            out.push(GoverningClause {
                node_id: scope.clone(),
                goal: goal.clone(),
                mode: CodeBindingMode::Governed,
            });
        }
        out
    }
}

impl Lodestar {
    /// Complete a task using one authoritative, claim-bounded conformance check
    /// (ADR-0009). The optional semantic judge is not invoked again here.
    pub fn complete_task(
        &self,
        id: &str,
        agent: &str,
        evidence: &ConformanceEvidence,
        check: &ConformanceCheck,
    ) -> Result<(bool, ConformanceResult)> {
        let now = now_unix();
        let agent = self.resolve_agent(agent)?;
        let task = self
            .store
            .get_task(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))?;
        self.validate_claim_evidence(&task, agent, evidence, now)?;
        let serialized = serde_json::to_string(evidence)?;
        let record = self
            .store
            .conformance_record(check.id)?
            .ok_or_else(|| LodestarError::NotFound(format!("conformance check {}", check.id)))?;
        let findings = check.findings.join("; ");
        let claim_started_at = task.claim_started_at.unwrap_or(now);
        if record.task_id.as_deref() != Some(id)
            || record.evidence_schema_version != evidence.schema_version
            || record.evidence != serialized
            || record.verdict != check.verdict
            || record.findings != findings
            || record.checked_at < claim_started_at
            || record.checked_at > now
        {
            return Err(LodestarError::Invalid(format!(
                "conformance check {} does not match the live task claim and evidence",
                check.id
            )));
        }
        let expected_token = self.conformance_token(check.id, evidence, check, Some(&task))?;
        if check.token != expected_token {
            return Err(LodestarError::Invalid(format!(
                "conformance check {} is stale; check the evidence again",
                check.id
            )));
        }
        let conformance = ConformanceResult {
            verdict: check.verdict,
            findings: check.findings.clone(),
        };
        let target_status = match conformance.verdict {
            Verdict::Aligned => TaskStatus::Done,
            Verdict::Violation => TaskStatus::Blocked,
            Verdict::Drift | Verdict::NeedsHuman => TaskStatus::InReview,
        };
        if !self.store.transition_with_checked_conformance(
            id,
            agent,
            check.id,
            conformance.verdict,
            target_status,
            now,
        )? {
            return Err(LodestarError::Invalid(format!(
                "task {id} claim changed before conformance could be recorded"
            )));
        }
        Ok((conformance.verdict == Verdict::Aligned, conformance))
    }

    /// Check evidence without changing task state; uses the completion evaluator.
    pub fn check_conformance(
        &self,
        evidence: &ConformanceEvidence,
        task_id: Option<&str>,
    ) -> Result<ConformanceCheck> {
        let resolved_task_id = match (task_id, evidence.task_id.as_deref()) {
            (Some(left), Some(right)) if left != right => {
                return Err(LodestarError::Invalid(
                    "evidence task_id does not match requested task".to_string(),
                ));
            }
            (Some(id), _) | (_, Some(id)) => Some(id),
            (None, None) => None,
        };
        let task = match resolved_task_id {
            Some(id) => Some(
                self.store
                    .get_task(id)?
                    .ok_or_else(|| LodestarError::NotFound(id.to_string()))?,
            ),
            None => None,
        };
        if let Some(task) = task.as_ref() {
            let agent = self.resolve_agent(&evidence.agent_id)?;
            self.validate_claim_evidence(task, agent, evidence, now_unix())?;
        } else {
            self.validate_evidence_shape(evidence)?;
        }
        let conformance = self.evaluate_conformance(evidence, task.as_ref())?;
        let serialized = serde_json::to_string(evidence)?;
        let findings = conformance.findings.join("; ");
        let id = self.store.record_conformance(
            resolved_task_id,
            ConformanceAudit {
                evidence_schema_version: evidence.schema_version,
                evidence: &serialized,
                verdict: conformance.verdict,
                findings: &findings,
            },
            now_unix(),
        )?;
        let mut checked = ConformanceCheck {
            id,
            token: String::new(),
            verdict: conformance.verdict,
            findings: conformance.findings,
        };
        checked.token = self.conformance_token(id, evidence, &checked, task.as_ref())?;
        Ok(checked)
    }

    fn conformance_token(
        &self,
        id: i64,
        evidence: &ConformanceEvidence,
        check: &ConformanceCheck,
        task: Option<&Task>,
    ) -> Result<String> {
        let mut basis = Vec::new();
        if let Some(task) = task {
            // `claim_lapses` belongs in the basis because the window start no
            // longer moves when the same owner re-claims (ADR-0048). Without it
            // a lease could lapse between a check and its completion and the
            // token would still match, letting a continuous-window verdict
            // certify a window that had since acquired a hole.
            basis.push(format!(
                "claim:{}:{}:{}:{}:{}",
                task.id,
                task.goal_id,
                task.owner.as_deref().unwrap_or_default(),
                task.claim_started_at.unwrap_or_default(),
                task.claim_lapses
            ));
            let goal = self
                .store
                .get_goal(&task.goal_id)?
                .ok_or_else(|| LodestarError::NotFound(task.goal_id.clone()))?;
            basis.push(format!("task-goal:{}", serde_json::to_string(&goal)?));
        }

        let mut nodes = evidence.changed_node_ids.clone();
        nodes.sort();
        nodes.dedup();
        for node in &nodes {
            for binding in self.store.active_bindings_for_node(node)? {
                basis.push(format!(
                    "binding:{node}:{}:{}",
                    binding.mode.as_str(),
                    serde_json::to_string(&binding.goal)?
                ));
            }
        }
        let changed: HashSet<&str> = nodes.iter().map(String::as_str).collect();
        for knowledge in self.store.active_knowledge(now_unix())? {
            if knowledge
                .referenced_nodes()
                .iter()
                .any(|node| changed.contains(node.as_str()))
            {
                basis.push(format!("knowledge:{}", serde_json::to_string(&knowledge)?));
            }
        }

        // Policy identity (ADR-0034). A token must not survive a change to the
        // constitution that authorised it, or to the controls that resolve its
        // clauses: a check issued under one policy is not evidence about
        // another. Recording the control *version* matters as much as its id,
        // because a redefined mechanism can reach a different verdict from the
        // same observation.
        if let Some(version) = self.store.active_constitution_version()? {
            basis.push(format!("constitution:{}:{}", version.id, version.version));
        }
        let mut clause_ids: Vec<String> = Vec::new();
        for node in &nodes {
            for binding in self.store.active_bindings_for_node(node)? {
                clause_ids.push(binding.goal.id);
            }
        }
        clause_ids.sort();
        clause_ids.dedup();
        for clause_id in &clause_ids {
            for control in self.store.controls_for_clause(clause_id)? {
                basis.push(format!(
                    "control:{}:{}:{}:{}",
                    control.id,
                    control.clause_id,
                    control.version,
                    control.power.as_str()
                ));
            }
            // Waiver state (SPEC-CONSTITUTION §9). A check made while an
            // exception was in force is not evidence about a world where it was
            // revoked, and one made under enforcement is not evidence about a
            // world where an exception was since granted. Recording `expires_at`
            // as well as status means a token also stops matching once the
            // waiver lapses — expiry restores enforcement without anyone
            // rewriting a row, so nothing else would notice.
            for waiver in self.store.waivers_for_clause(clause_id)? {
                basis.push(format!(
                    "waiver:{}:{}:{}:{}:{}",
                    waiver.id,
                    waiver.clause_id,
                    waiver.scope,
                    waiver.status.as_str(),
                    waiver.expires_at
                ));
            }
        }
        basis.sort();

        let mut hasher = Sha256::new();
        hasher.update(id.to_le_bytes());
        hasher.update(serde_json::to_vec(evidence)?);
        hasher.update(check.verdict.as_str().as_bytes());
        hasher.update(serde_json::to_vec(&check.findings)?);
        hasher.update(basis.join("\n").as_bytes());
        Ok(hasher
            .finalize()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect())
    }

    /// Score evidence against governing intent, then layer ADR-0022 advisory
    /// knowledge on top. The base pass owns all hard verdicts (Drift / Violation /
    /// NeedsHuman / Aligned from goals and the Constitution); the knowledge pass
    /// may only add advisory findings and, at most, nudge an otherwise-`Aligned`
    /// verdict to `NeedsHuman` — it can never harden a verdict or emit `Violation`.
    fn evaluate_conformance(
        &self,
        evidence: &ConformanceEvidence,
        task: Option<&Task>,
    ) -> Result<ConformanceResult> {
        let mut result = self.evaluate_base_conformance(evidence, task)?;
        self.apply_knowledge_advisory(evidence, &mut result)?;
        Ok(result)
    }

    /// Consult learned knowledge (ADR-0022). When the evidence's changed nodes
    /// intersect the nodes a proven regularity references, attach an ADVISORY
    /// finding and, at most, escalate an `Aligned` verdict to `NeedsHuman` so a
    /// human looks. Knowledge is revalidated and decaying, so it MUST NOT emit a
    /// `Violation` or otherwise harden the verdict — only the Constitution
    /// (constraint / invariant goals) hard-fails. This read path stays
    /// deterministic: no LLM.
    fn apply_knowledge_advisory(
        &self,
        evidence: &ConformanceEvidence,
        result: &mut ConformanceResult,
    ) -> Result<()> {
        if evidence.changed_node_ids.is_empty() {
            return Ok(());
        }
        let changed: HashSet<&str> = evidence
            .changed_node_ids
            .iter()
            .map(String::as_str)
            .collect();
        let mut matched = false;
        for knowledge in self.store.active_knowledge(now_unix())? {
            if knowledge
                .referenced_nodes()
                .iter()
                .any(|node| changed.contains(node.as_str()))
            {
                matched = true;
                result.findings.push(format!(
                    "advisory: learned knowledge {} — {}",
                    knowledge.id, knowledge.statement
                ));
            }
        }
        if matched && result.verdict == Verdict::Aligned {
            result.verdict = Verdict::NeedsHuman;
        }
        Ok(())
    }

    fn evaluate_base_conformance(
        &self,
        evidence: &ConformanceEvidence,
        task: Option<&Task>,
    ) -> Result<ConformanceResult> {
        let mut findings = Vec::new();
        if evidence.changed_node_ids.is_empty() || evidence.provenance.is_empty() {
            findings.push("evidence contains no provenance-bearing mutation".to_string());
            return Ok(ConformanceResult {
                verdict: Verdict::NeedsHuman,
                findings,
            });
        }

        let task_goal_id = task.map(|t| t.goal_id.as_str());
        let covered = match task {
            Some(task) => self.store.goal_coverage(&task.id)?,
            None => Vec::new(),
        };
        let governing = self.resolve_governing_clauses_covering(
            &evidence.changed_node_ids,
            task_goal_id,
            &covered,
        )?;

        // A hard forbid_change lock overrides everything: any change is a breach.
        // It resolves through the typed-control machinery (ADR-0034) but supplies
        // its own declared consequence rather than reading the clause's
        // (ADR-0036) — a human who placed a lock already chose that power, and an
        // incomplete enforcement contract must not silently soften it.
        //
        // A valid waiver is the one thing that stands it down (§9). Note it does
        // not make the change invisible: the finding names the waiver and its
        // approver, so the audit records that an exception was used rather than
        // that nothing happened.
        if let Some((node, goal)) = governing.forbid.first() {
            let now = now_unix();
            match self.excusing_waiver(goal, node, now)? {
                Some(waiver) => findings.push(format!(
                    "{} forbids changes to {node}, waived by {} until {} ({})",
                    goal.id, waiver.approved_by, waiver.expires_at, waiver.id
                )),
                None => {
                    let control = forbid_change_control(&goal.id);
                    let observation = forbid_change_observation(&goal.id, node, now);
                    let resolved =
                        resolve_with_declared(Some(Consequence::Block), &control, &observation);
                    findings.push(format!("{} forbids changes to {node}", goal.id));
                    findings.push(resolved.finding);
                    return Ok(ConformanceResult {
                        verdict: if resolved.effective == Consequence::Block {
                            Verdict::Violation
                        } else {
                            Verdict::NeedsHuman
                        },
                        findings,
                    });
                }
            }
        }

        // Governed code touched by a goal that no covering task serves is drift.
        if !governing.other.is_empty() {
            let now = now_unix();
            let mut unwaived: Vec<String> = Vec::new();
            for (node, goal) in &governing.other {
                match self.excusing_waiver(goal, node, now)? {
                    Some(waiver) => findings.push(format!(
                        "{} governs {node} without a covering task, waived by {} until {} ({})",
                        goal.id, waiver.approved_by, waiver.expires_at, waiver.id
                    )),
                    None => unwaived.push(goal.id.clone()),
                }
            }
            unwaived.sort();
            unwaived.dedup();
            if !unwaived.is_empty() {
                findings.push(format!(
                    "governed code changed without a covering task: {}",
                    unwaived.join(", ")
                ));
                return Ok(ConformanceResult {
                    verdict: Verdict::Drift,
                    findings,
                });
            }
        }
        let touched_task_goal = !governing.in_scope.is_empty();
        let Some(task) = task else {
            findings.push("no governed code touched".to_string());
            return Ok(ConformanceResult {
                verdict: Verdict::Aligned,
                findings,
            });
        };
        if !touched_task_goal {
            findings.push("evidence does not touch code bound to the task goal".to_string());
            return Ok(ConformanceResult {
                verdict: Verdict::NeedsHuman,
                findings,
            });
        }

        let goal = self
            .store
            .get_goal(&task.goal_id)?
            .ok_or_else(|| LodestarError::NotFound(task.goal_id.clone()))?;
        if goal.kind.is_normative() {
            match self.judge_conformance(&goal.statement, &evidence.summary) {
                Ok((verdict, rationale)) if verdict == "aligned" => {
                    findings.push(format!("semantic check aligned: {rationale}"));
                }
                Ok((verdict, rationale)) if verdict == "violation" => {
                    findings.push(format!("semantic check found a violation: {rationale}"));
                    return Ok(ConformanceResult {
                        verdict: Verdict::Violation,
                        findings,
                    });
                }
                Ok((_, rationale)) => {
                    findings.push(format!("semantic check needs human review: {rationale}"));
                    return Ok(ConformanceResult {
                        verdict: Verdict::NeedsHuman,
                        findings,
                    });
                }
                Err(_) => {
                    findings.push("semantic check unavailable".to_string());
                    return Ok(ConformanceResult {
                        verdict: Verdict::NeedsHuman,
                        findings,
                    });
                }
            }
        }

        findings.push(format!("evidence covers task goal {}", task.goal_id));

        // A discontinuous evidence window cannot certify itself (ADR-0048,
        // ADR-0034 ceiling rule). The window now survives a lapse so earlier
        // work stays provable, but a lapse means there was a stretch in which
        // this agent held no lease, and nothing here can tell whether work fell
        // into it. That is an unknown, not a pass.
        //
        // The cap is on the task, not on the submitted interval, and that is
        // deliberate: if it depended on whether the hole fell inside the
        // evidence span, an agent could dodge it by submitting a narrower span
        // — which is exactly the laundering this rule exists to stop.
        if task.claim_lapses > 0 {
            findings.push(format!(
                "evidence window is discontinuous: the lease lapsed {} time(s), \
                 leaving {}s unleased, which a human confirms",
                task.claim_lapses, task.unleased_seconds
            ));
            return Ok(ConformanceResult {
                verdict: Verdict::NeedsHuman,
                findings,
            });
        }

        // Declared cross-goal coverage informs; it never self-certifies
        // (ADR-0041, ADR-0034 ceiling rule). If the evidence is in scope only
        // because the task declared another goal at creation, a human confirms
        // the breadth — but the audit names which declarations it leaned on, so
        // this reads as reviewable breadth rather than as drift.
        if !governing.relied_on_coverage.is_empty() {
            findings.push(format!(
                "in scope via declared coverage, which a human confirms: {}",
                governing.relied_on_coverage.join(", ")
            ));
            return Ok(ConformanceResult {
                verdict: Verdict::NeedsHuman,
                findings,
            });
        }

        Ok(ConformanceResult {
            verdict: Verdict::Aligned,
            findings,
        })
    }

    /// Resolve which active clauses govern a set of intended or changed nodes,
    /// classified by how each relates to a covering task's own goal. This is the
    /// one place the constitution is read against a change scope, shared by
    /// retrospective conformance (`evaluate_base_conformance`) and the
    /// forward-looking `advise` (ADR-0029) so neither forks the rule. A
    /// documentation node contributes only a `forbid_change` lock; a `governed`
    /// binding to a doc is ignored at read time (a changelog touch must not
    /// drift), and no stored binding is mutated.
    pub(crate) fn resolve_governing_clauses(
        &self,
        node_ids: &[String],
        task_goal_id: Option<&str>,
    ) -> Result<GoverningClauses> {
        self.resolve_governing_clauses_covering(node_ids, task_goal_id, &[])
    }

    /// As [`Self::resolve_governing_clauses`], but also treating a binding to
    /// any goal in `covered` as in scope (ADR-0041). `covered` holds the
    /// additional goals a task declared at creation; the goals actually relied
    /// on are recorded so the caller can report which declarations mattered.
    pub(crate) fn resolve_governing_clauses_covering(
        &self,
        node_ids: &[String],
        task_goal_id: Option<&str>,
        covered: &[String],
    ) -> Result<GoverningClauses> {
        let mut resolved = GoverningClauses::default();
        for node in node_ids {
            let node_is_doc = is_documentation_node(node);
            for binding in self.store.active_bindings_for_node(node)? {
                if binding.mode == CodeBindingMode::ForbidChange {
                    resolved.forbid.push((node.clone(), binding.goal));
                    continue;
                }
                if node_is_doc {
                    continue;
                }
                match task_goal_id {
                    Some(goal_id) if binding.goal.id == goal_id => {
                        resolved.in_scope.push((node.clone(), binding.goal))
                    }
                    _ if covered.contains(&binding.goal.id) => {
                        resolved.relied_on_coverage.push(binding.goal.id.clone());
                        resolved.in_scope.push((node.clone(), binding.goal))
                    }
                    _ => resolved.other.push((node.clone(), binding.goal)),
                }
            }
        }
        resolved.relied_on_coverage.sort();
        resolved.relied_on_coverage.dedup();
        Ok(resolved)
    }

    /// Clauses governing an intended *procedural* action (ADR-0034).
    ///
    /// A workflow clause declares a `workflow:` scope instead of binding to code
    /// nodes, so it resolves by scope match rather than by binding lookup — a
    /// rule like "a protected branch advances only by reviewed merge" governs an
    /// action, and there is no artifact to bind it to.
    ///
    /// A parent token governs its children, so a clause scoped `workflow:git`
    /// covers an intent of `workflow:git.publish`. The reverse never holds: a
    /// clause about publishing does not govern every git action.
    pub(crate) fn resolve_workflow_clauses(
        &self,
        scopes: &[String],
    ) -> Result<Vec<(String, Goal)>> {
        if scopes.is_empty() {
            return Ok(Vec::new());
        }
        let mut resolved = Vec::new();
        for goal in self.store.goals_by_status(GoalStatus::Active)? {
            let Some(declared) = goal.scope.as_deref() else {
                continue;
            };
            if !scope::is_workflow(declared) {
                continue;
            }
            if let Some(intended) = scopes
                .iter()
                .find(|intended| scope::workflow_governs(declared, intended))
            {
                resolved.push((intended.clone(), goal));
            }
        }
        Ok(resolved)
    }

    fn validate_evidence_shape(&self, evidence: &ConformanceEvidence) -> Result<()> {
        if evidence.schema_version != 1 {
            return Err(LodestarError::Invalid(format!(
                "unsupported evidence schema version {}",
                evidence.schema_version
            )));
        }
        if evidence.started_at > evidence.ended_at {
            return Err(LodestarError::Invalid(
                "evidence start must not be after its end".to_string(),
            ));
        }
        if evidence.agent_id.trim().is_empty() {
            return Err(LodestarError::Invalid(
                "evidence agent must not be empty".to_string(),
            ));
        }
        if evidence.execution_ids.len() > MAX_EVIDENCE_EVENTS
            || evidence.commit_ids.len() > MAX_EVIDENCE_EVENTS
            || evidence.provenance.len() > MAX_EVIDENCE_PROVENANCE
            || evidence.summary.len() > MAX_EVIDENCE_SUMMARY_BYTES
        {
            return Err(LodestarError::Invalid(
                "evidence exceeds the bounded ADR-0009 contract".to_string(),
            ));
        }
        if !evidence
            .successful_execution_ids
            .iter()
            .all(|id| evidence.execution_ids.contains(id))
        {
            return Err(LodestarError::Invalid(
                "successful executions must be included in execution_ids".to_string(),
            ));
        }
        let agent_node_id = format!("agent:{}", evidence.agent_id);
        for event_id in evidence
            .execution_ids
            .iter()
            .chain(evidence.commit_ids.iter())
        {
            if !evidence.provenance.iter().any(|fact| {
                fact.source_id == agent_node_id
                    && fact.target_id == *event_id
                    && fact.relation == "observed"
            }) {
                return Err(LodestarError::Invalid(format!(
                    "event {event_id} lacks agent observation provenance"
                )));
            }
        }
        for changed_id in &evidence.changed_node_ids {
            if !evidence.provenance.iter().any(|fact| {
                fact.target_id == *changed_id
                    && matches!(fact.relation.as_str(), "modified" | "refactored")
                    && (evidence.execution_ids.contains(&fact.source_id)
                        || evidence.commit_ids.contains(&fact.source_id))
            }) {
                return Err(LodestarError::Invalid(format!(
                    "changed node {changed_id} lacks mutation provenance"
                )));
            }
        }
        for failed_id in &evidence.failed_node_ids {
            if !evidence.provenance.iter().any(|fact| {
                fact.target_id == *failed_id
                    && fact.relation == "failed_on"
                    && evidence.execution_ids.contains(&fact.source_id)
            }) {
                return Err(LodestarError::Invalid(format!(
                    "failed node {failed_id} lacks failure provenance"
                )));
            }
        }
        Ok(())
    }

    fn validate_claim_evidence(
        &self,
        task: &Task,
        agent: &str,
        evidence: &ConformanceEvidence,
        now: i64,
    ) -> Result<()> {
        self.validate_evidence_shape(evidence)?;
        if evidence.task_id.as_deref() != Some(task.id.as_str()) {
            return Err(LodestarError::Invalid(
                "evidence task_id does not identify the claimed task".to_string(),
            ));
        }
        if evidence.agent_id != agent || task.owner.as_deref() != Some(agent) {
            return Err(LodestarError::Invalid(
                "evidence agent does not own the task".to_string(),
            ));
        }
        let lease_expired = match task.lease_expires_at {
            Some(end) => end < now,
            None => true,
        };
        if task.status != TaskStatus::Claimed || lease_expired {
            return Err(LodestarError::Invalid(
                "task does not have a live claim".to_string(),
            ));
        }
        let claim_started_at = task.claim_started_at.ok_or_else(|| {
            LodestarError::Invalid("task claim has no evidence-window start".to_string())
        })?;
        if evidence.started_at < claim_started_at
            || evidence.ended_at > now
            || evidence.ended_at > task.lease_expires_at.unwrap_or(evidence.ended_at)
        {
            return Err(LodestarError::Invalid(
                "evidence interval falls outside the live claim".to_string(),
            ));
        }
        Ok(())
    }

    /// The durable, append-only conformance evidence chain for a task: each
    /// record carries its stable id, the recorded evidence bundle, the verdict,
    /// findings, and when it was checked — the resolvable link proving how (and
    /// whether) the task reached completion.
    pub fn conformance_history(&self, task_id: &str) -> Result<Vec<crate::ConformanceRecord>> {
        self.store.conformance_history(task_id)
    }
}

#[cfg(test)]
mod tests {
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    use super::*;
    use crate::controls::{Control, ControlKind, ControlStatus, EnforcementPower};
    use crate::facade::test_support::engine;
    use crate::{EvidenceProvenance, GoalKind};

    #[test]
    fn completion_uses_the_aligned_preflight_for_identical_evidence() {
        // Bug regression: check_conformance and complete_task used to invoke the
        // optional judge independently, so identical evidence could preflight as
        // aligned and then strand the task in review on a different model answer.
        let judge_calls = Arc::new(AtomicUsize::new(0));
        let calls = Arc::clone(&judge_calls);
        let e = Lodestar::open_in_memory()
            .unwrap()
            .with_test_judge(move |_, _| {
                let verdict = if calls.fetch_add(1, Ordering::SeqCst) == 0 {
                    "aligned"
                } else {
                    "needs_human"
                };
                Ok((verdict.into(), format!("stub returned {verdict}")))
            });
        let goal = e
            .define_goal(
                GoalKind::Constraint,
                "Clean delivery",
                "changes use clean design",
                None,
            )
            .unwrap();
        let node_id = "artifact:src/delivery.rs";
        e.link_goal_to_code(&goal.id, &[node_id.into()], CodeBindingMode::Governed)
            .unwrap();
        let task = e
            .create_task(&goal.id, "fix delivery", "same evidence stays aligned")
            .unwrap();
        e.claim_task(&task.id, "agent-a", 300).unwrap();
        let claimed = e.store.get_task(&task.id).unwrap().unwrap();
        let mut evidence = test_evidence(Some(task.id.clone()), "agent-a", node_id);
        evidence.started_at = claimed.claim_started_at.unwrap();
        evidence.ended_at = now_unix();

        let checked = e.check_conformance(&evidence, Some(&task.id)).unwrap();
        assert_eq!(checked.verdict, Verdict::Aligned);

        let (completed, completion) = e
            .complete_task(&task.id, "agent-a", &evidence, &checked)
            .unwrap();
        assert!(completed);
        assert_eq!(completion.verdict, checked.verdict);
        assert_eq!(completion.findings, checked.findings);
        assert_eq!(
            e.store.get_task(&task.id).unwrap().unwrap().status,
            TaskStatus::Done
        );
        let history = e.conformance_history(&task.id).unwrap();
        assert_eq!(history.len(), 1);
        assert_eq!(history[0].id, checked.id);
        assert_eq!(judge_calls.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn completion_rejects_changed_evidence_or_intent_state() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Ship search", "add search", None)
            .unwrap();
        let node_id = "artifact:src/search.rs";
        e.link_goal_to_code(&goal.id, &[node_id.into()], CodeBindingMode::Governed)
            .unwrap();
        let task = e.create_task(&goal.id, "wire search", "done").unwrap();
        e.claim_task(&task.id, "agent-a", 300).unwrap();
        let claimed = e.store.get_task(&task.id).unwrap().unwrap();
        let mut evidence = test_evidence(Some(task.id.clone()), "agent-a", node_id);
        evidence.started_at = claimed.claim_started_at.unwrap();
        evidence.ended_at = now_unix();
        let checked = e.check_conformance(&evidence, Some(&task.id)).unwrap();

        let mut changed_evidence = evidence.clone();
        changed_evidence.summary.push_str(" after preflight");
        assert!(e
            .complete_task(&task.id, "agent-a", &changed_evidence, &checked)
            .unwrap_err()
            .to_string()
            .contains("does not match"));

        let other_goal = e
            .define_goal(GoalKind::Objective, "Own search", "separate owner", None)
            .unwrap();
        e.link_goal_to_code(&other_goal.id, &[node_id.into()], CodeBindingMode::Governed)
            .unwrap();
        assert!(e
            .complete_task(&task.id, "agent-a", &evidence, &checked)
            .unwrap_err()
            .to_string()
            .contains("is stale"));
        assert_eq!(
            e.store.get_task(&task.id).unwrap().unwrap().status,
            TaskStatus::Claimed
        );
    }

    #[test]
    fn uncertain_checked_completion_is_reopenable_and_keeps_its_evidence_link() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Ship auth", "change auth", None)
            .unwrap();
        let task = e.create_task(&goal.id, "change auth", "done").unwrap();
        e.claim_task(&task.id, "agent-a", 300).unwrap();
        let claimed = e.store.get_task(&task.id).unwrap().unwrap();
        let evidence = ConformanceEvidence {
            schema_version: 1,
            task_id: Some(task.id.clone()),
            agent_id: "agent-a".into(),
            started_at: claimed.claim_started_at.unwrap(),
            ended_at: now_unix(),
            changed_node_ids: Vec::new(),
            failed_node_ids: Vec::new(),
            execution_ids: Vec::new(),
            successful_execution_ids: Vec::new(),
            commit_ids: Vec::new(),
            summary: "no mutation evidence".into(),
            provenance: Vec::new(),
        };
        let checked = e.check_conformance(&evidence, Some(&task.id)).unwrap();
        assert_eq!(checked.verdict, Verdict::NeedsHuman);

        let (completed, result) = e
            .complete_task(&task.id, "agent-a", &evidence, &checked)
            .unwrap();
        assert!(!completed);
        assert_eq!(result.verdict, Verdict::NeedsHuman);
        assert!(e.reopen_task(&task.id).unwrap());
        assert_eq!(
            e.store.get_task(&task.id).unwrap().unwrap().status,
            TaskStatus::Open
        );
        let history = e.conformance_history(&task.id).unwrap();
        assert_eq!(history.len(), 1);
        assert_eq!(history[0].id, checked.id);
    }

    #[test]
    fn conformance_flags_ungoverned_as_aligned_and_governed_as_drift() {
        let e = engine();
        let g = e
            .define_goal(
                GoalKind::Constraint,
                "Auth stays typed",
                "no stringly auth",
                None,
            )
            .unwrap();
        e.link_goal_to_code(
            &g.id,
            &["artifact:src/auth.rs".into()],
            CodeBindingMode::Governed,
        )
        .unwrap();

        let free_evidence = test_evidence(None, "agent-a", "artifact:src/unrelated.rs");
        let free = e.check_conformance(&free_evidence, None).unwrap();
        assert_eq!(free.verdict, Verdict::Aligned);

        let drift_evidence = test_evidence(None, "agent-a", "artifact:src/auth.rs");
        let drift = e.check_conformance(&drift_evidence, None).unwrap();
        assert_eq!(drift.verdict, Verdict::Drift);
    }

    // ADR-0041. Cross-cutting work used to be indistinguishable from an
    // unsanctioned edit: both returned Drift with "governed code changed
    // without a covering task". Coverage declared at creation separates them —
    // and, because it is the agent's own claim about its own breadth, it buys a
    // review rather than a pass (ADR-0034 ceiling rule).
    #[test]
    fn declared_coverage_turns_cross_goal_drift_into_reviewable_breadth() {
        let e = engine();
        let primary = e
            .define_goal(GoalKind::Objective, "Intent plane", "intent", None)
            .unwrap();
        let other = e
            .define_goal(GoalKind::Objective, "Context graph", "graph", None)
            .unwrap();
        e.link_goal_to_code(
            &primary.id,
            &["artifact:src/intent.rs".into()],
            CodeBindingMode::Governed,
        )
        .unwrap();
        e.link_goal_to_code(
            &other.id,
            &["artifact:src/graph.rs".into()],
            CodeBindingMode::Governed,
        )
        .unwrap();
        let cross_cutting = |task_id: &str| {
            let claimed = e.store.get_task(task_id).unwrap().unwrap();
            let mut evidence = test_evidence(
                Some(task_id.to_string()),
                "agent-a",
                "artifact:src/intent.rs",
            );
            evidence.started_at = claimed.claim_started_at.unwrap();
            evidence.ended_at = now_unix();
            evidence
                .changed_node_ids
                .push("artifact:src/graph.rs".into());
            evidence.provenance.push(EvidenceProvenance {
                source_id: "execution:proof".into(),
                target_id: "artifact:src/graph.rs".into(),
                relation: "modified".into(),
            });
            evidence
        };

        // 1. Undeclared coverage is unchanged: still drift.
        let bare = e.create_task(&primary.id, "Bare", "done").unwrap();
        assert!(e.claim_task(&bare.id, "agent-a", 600).unwrap());
        let drift = e
            .check_conformance(&cross_cutting(&bare.id), Some(&bare.id))
            .unwrap();
        assert_eq!(drift.verdict, Verdict::Drift);

        // 2 + 3. Declared coverage is in scope, caps at needs_human, and the
        // audit names the declaration the verdict leaned on.
        let covering = e
            .create_task_covering(
                &primary.id,
                "Cross",
                "done",
                None,
                std::slice::from_ref(&other.id),
            )
            .unwrap();
        assert!(e.claim_task(&covering.id, "agent-a", 600).unwrap());
        let reviewed = e
            .check_conformance(&cross_cutting(&covering.id), Some(&covering.id))
            .unwrap();
        assert_eq!(reviewed.verdict, Verdict::NeedsHuman);
        assert!(
            reviewed.findings.iter().any(|f| f.contains(&other.id)),
            "findings should name the declared goal: {:?}",
            reviewed.findings
        );
        assert!(
            !reviewed
                .findings
                .iter()
                .any(|f| f.contains("without a covering task")),
            "declared breadth must not read as drift: {:?}",
            reviewed.findings
        );
    }

    // ADR-0041 point 4: a declaration the evidence never leaned on changes
    // nothing. Over-declaring must not quietly demote an otherwise clean task.
    #[test]
    fn coverage_the_evidence_never_touched_leaves_the_verdict_alone() {
        let e = engine();
        let primary = e
            .define_goal(GoalKind::Objective, "Intent plane", "intent", None)
            .unwrap();
        let unused = e
            .define_goal(GoalKind::Objective, "Context graph", "graph", None)
            .unwrap();
        e.link_goal_to_code(
            &primary.id,
            &["artifact:src/intent.rs".into()],
            CodeBindingMode::Governed,
        )
        .unwrap();

        let task = e
            .create_task_covering(
                &primary.id,
                "Narrow",
                "done",
                None,
                std::slice::from_ref(&unused.id),
            )
            .unwrap();
        assert!(e.claim_task(&task.id, "agent-a", 600).unwrap());
        let claimed = e.store.get_task(&task.id).unwrap().unwrap();
        let mut evidence =
            test_evidence(Some(task.id.clone()), "agent-a", "artifact:src/intent.rs");
        evidence.started_at = claimed.claim_started_at.unwrap();
        evidence.ended_at = now_unix();

        let result = e.check_conformance(&evidence, Some(&task.id)).unwrap();
        assert_eq!(result.verdict, Verdict::Aligned);
    }

    // ADR-0041 point 5: coverage is fixed at creation. Declaring an unknown
    // goal, or the task's own goal, is refused rather than quietly ignored.
    #[test]
    fn coverage_is_validated_at_creation_and_has_no_later_mutator() {
        let e = engine();
        let goal = e
            .define_goal(GoalKind::Objective, "Intent plane", "intent", None)
            .unwrap();

        assert!(e
            .create_task_covering(&goal.id, "Unknown", "done", None, &["goal:nope".into()])
            .is_err());
        assert!(e
            .create_task_covering(
                &goal.id,
                "Self",
                "done",
                None,
                std::slice::from_ref(&goal.id)
            )
            .is_err());

        let plain = e.create_task(&goal.id, "Plain", "done").unwrap();
        assert!(e.task_goal_coverage(&plain.id).unwrap().is_empty());
    }

    #[test]
    fn a_control_version_bump_invalidates_a_previously_issued_token() {
        // ADR-0034: a check issued under one policy is not evidence about
        // another. A redefined mechanism can reach a different verdict from the
        // same observation, so the token must not survive the change.
        let e = engine();
        let goal = e
            .define_goal(
                GoalKind::Invariant,
                "Reviewed merge",
                "A protected branch advances only by reviewed merge.",
                None,
            )
            .unwrap();
        let node = "artifact:crates/core/src/publish.rs".to_string();
        e.link_goal_to_code(
            &goal.id,
            std::slice::from_ref(&node),
            CodeBindingMode::Governed,
        )
        .unwrap();
        let control = Control {
            id: "control:branch-policy".into(),
            clause_id: goal.id.clone(),
            kind: ControlKind::Check,
            power: EnforcementPower::Mechanical,
            version: 1,
            configuration: None,
            status: ControlStatus::Active,
        };
        e.register_control(&control).unwrap();

        let evidence = test_evidence(None, "agent-a", &node);
        let first = e.check_conformance(&evidence, None).unwrap();

        // Redefine what the control does. Same evidence, same clause.
        e.register_control(&Control {
            version: 2,
            ..control
        })
        .unwrap();
        let second = e.check_conformance(&evidence, None).unwrap();

        assert_ne!(
            first.token, second.token,
            "a token must not survive a control redefinition"
        );
    }

    #[test]
    fn a_lock_still_blocks_when_its_clause_declares_no_consequence() {
        // ADR-0036 regression: forbid_change now resolves through the typed
        // control machinery, but supplies its own declared consequence. Reading
        // it from the clause instead would let an incomplete enforcement
        // contract silently soften every existing lock from violation to
        // needs_human — invisible until a breach failed to block.
        let e = engine();
        let goal = e
            .define_goal(
                GoalKind::Invariant,
                "Frozen schema",
                "The schema file must not change.",
                None,
            )
            .unwrap();
        assert!(
            goal.consequence.is_none(),
            "a freshly defined clause declares no consequence"
        );
        let node = "artifact:crates/core/src/schema.sql".to_string();
        e.link_goal_to_code(
            &goal.id,
            std::slice::from_ref(&node),
            CodeBindingMode::ForbidChange,
        )
        .unwrap();

        let evidence = test_evidence(None, "agent-a", &node);
        let res = e.check_conformance(&evidence, None).unwrap();
        assert_eq!(res.verdict, Verdict::Violation);
        assert!(res
            .findings
            .iter()
            .any(|f| f.contains("forbids changes to")));
        assert!(res
            .findings
            .iter()
            .any(|f| f.contains("control:forbid_change")));
    }

    /// A locked node under a clause that permits bounded exceptions.
    fn locked_waivable_clause(e: &Lodestar, node: &str) -> Goal {
        let goal = e
            .define_goal(
                GoalKind::Invariant,
                "Frozen schema",
                "The schema file must not change.",
                None,
            )
            .unwrap();
        let clause = e
            .store
            .complete_clause_contract(
                &goal.id,
                "artifact:crates/**",
                "schema diff",
                Some(Consequence::Block),
                true,
                None,
            )
            .unwrap();
        e.link_goal_to_code(
            &goal.id,
            std::slice::from_ref(&node.to_string()),
            CodeBindingMode::ForbidChange,
        )
        .unwrap();
        clause
    }

    fn waiver_request(
        clause_id: &str,
        scope: &str,
        expires_at: i64,
    ) -> crate::waiver::WaiverRequest {
        crate::waiver::WaiverRequest {
            clause_id: clause_id.to_string(),
            scope: scope.to_string(),
            reason: "Release blocker; remediation tracked.".into(),
            approved_by: "monk-eee".into(),
            expires_at,
            remediation_task_id: None,
        }
    }

    #[test]
    fn a_valid_waiver_stands_down_a_lock_without_hiding_that_it_was_used() {
        // §9: an exception is not a hidden bypass. The verdict changes, but the
        // record still names the waiver and its approver — otherwise a waived
        // breach and a change that never touched a locked node would be
        // indistinguishable in the audit.
        let e = engine();
        let node = "artifact:crates/core/src/schema.sql".to_string();
        let clause = locked_waivable_clause(&e, &node);

        let evidence = test_evidence(None, "agent-a", &node);
        assert_eq!(
            e.check_conformance(&evidence, None).unwrap().verdict,
            Verdict::Violation
        );

        let waiver = e
            .grant_waiver(&waiver_request(&clause.id, &node, now_unix() + 3_600))
            .unwrap();
        let waived = e.check_conformance(&evidence, None).unwrap();
        assert_ne!(waived.verdict, Verdict::Violation);
        assert!(
            waived
                .findings
                .iter()
                .any(|f| f.contains(&waiver.id) && f.contains("monk-eee")),
            "{:?}",
            waived.findings
        );
    }

    #[test]
    fn revocation_restores_enforcement_for_the_next_check() {
        let e = engine();
        let node = "artifact:crates/core/src/schema.sql".to_string();
        let clause = locked_waivable_clause(&e, &node);
        let evidence = test_evidence(None, "agent-a", &node);

        let waiver = e
            .grant_waiver(&waiver_request(&clause.id, &node, now_unix() + 3_600))
            .unwrap();
        assert_ne!(
            e.check_conformance(&evidence, None).unwrap().verdict,
            Verdict::Violation
        );

        e.revoke_waiver(&waiver.id, "monk-eee", "Fix landed")
            .unwrap();
        assert_eq!(
            e.check_conformance(&evidence, None).unwrap().verdict,
            Verdict::Violation,
            "revocation is immediate for future checks"
        );
    }

    #[test]
    fn an_expired_waiver_stops_excusing_without_anything_being_rewritten() {
        // Expiry is a query bound, not a status transition (§9). Nothing runs
        // to make this happen, which is exactly why it cannot be forgotten.
        let e = engine();
        let node = "artifact:crates/core/src/schema.sql".to_string();
        let clause = locked_waivable_clause(&e, &node);
        let now = now_unix();

        // Granted legitimately in the past — its expiry was in the future then —
        // and lapsed by the time the check runs. Written through the store so
        // the test can place it in the past without sleeping.
        let lapsed = e
            .store
            .grant_waiver(
                "waiver:lapsed",
                &waiver_request(&clause.id, &node, now - 1),
                now - 10,
            )
            .unwrap();
        assert!(lapsed.applies_to(&node, now - 10), "valid when granted");
        assert!(!lapsed.applies_to(&node, now), "lapsed by check time");

        let evidence = test_evidence(None, "agent-a", &node);
        assert_eq!(
            e.check_conformance(&evidence, None).unwrap().verdict,
            Verdict::Violation,
            "expiry restores enforcement with nothing having run"
        );
        assert_eq!(
            e.store.waiver(&lapsed.id).unwrap().unwrap().status,
            crate::waiver::WaiverStatus::Active,
            "a lapsed waiver keeps its status; history is not rewritten"
        );
    }

    #[test]
    fn granting_or_revoking_a_waiver_invalidates_a_stale_conformance_token() {
        // ADR-0025: a token proves a check was made under a specific policy
        // state. A waiver is part of that state, so a check made while an
        // exception was in force must not be spendable after it is withdrawn.
        let e = engine();
        let node = "artifact:crates/core/src/schema.sql".to_string();
        let clause = locked_waivable_clause(&e, &node);
        let evidence = test_evidence(None, "agent-a", &node);

        let before = e.check_conformance(&evidence, None).unwrap();
        let waiver = e
            .grant_waiver(&waiver_request(&clause.id, &node, now_unix() + 3_600))
            .unwrap();
        let during = e.check_conformance(&evidence, None).unwrap();
        assert_ne!(
            before.token, during.token,
            "granting changed the policy state"
        );

        e.revoke_waiver(&waiver.id, "monk-eee", "Fix landed")
            .unwrap();
        let after = e.check_conformance(&evidence, None).unwrap();
        assert_ne!(during.token, after.token, "revoking changed it again");
    }

    #[test]
    fn learned_knowledge_adds_advisory_and_nudges_aligned_to_needs_human() {
        let e = engine();
        // A proven regularity referencing a node (ADR-0022).
        e.consolidate(
            "changes to gizmo break the parser",
            &[
                "artifact:src/gizmo.rs".into(),
                "execution:2".into(),
                "execution:3".into(),
            ],
            0,
            10 * 24 * 3600,
        )
        .unwrap();

        // Ungoverned change would be Aligned on its own, but it touches a node a
        // learned regularity references, so an advisory finding attaches and the
        // verdict is nudged to NeedsHuman — never Violation.
        let evidence = test_evidence(None, "agent-a", "artifact:src/gizmo.rs");
        let res = e.check_conformance(&evidence, None).unwrap();
        assert_eq!(res.verdict, Verdict::NeedsHuman);
        assert_ne!(res.verdict, Verdict::Violation);
        assert!(res
            .findings
            .iter()
            .any(|f| f.contains("advisory: learned knowledge")));
    }

    #[test]
    fn learned_knowledge_never_hardens_a_verdict_or_emits_violation() {
        let e = engine();
        // Governed code so the base verdict is Drift (no covering task).
        let g = e
            .define_goal(
                GoalKind::Constraint,
                "Parser typed",
                "no stringly parser",
                None,
            )
            .unwrap();
        e.link_goal_to_code(
            &g.id,
            &["artifact:src/parser.rs".into()],
            CodeBindingMode::Governed,
        )
        .unwrap();
        // A regularity that also references the changed node.
        e.consolidate(
            "changes to parser break the lexer",
            &[
                "artifact:src/parser.rs".into(),
                "execution:2".into(),
                "execution:3".into(),
            ],
            0,
            10 * 24 * 3600,
        )
        .unwrap();

        let evidence = test_evidence(None, "agent-a", "artifact:src/parser.rs");
        let res = e.check_conformance(&evidence, None).unwrap();
        // Knowledge annotates but never changes a non-Aligned verdict, and can
        // never produce a hard Violation — only the Constitution hard-fails.
        assert_eq!(res.verdict, Verdict::Drift);
        assert!(res
            .findings
            .iter()
            .any(|f| f.contains("advisory: learned knowledge")));
    }

    #[test]
    fn covering_task_without_evidence_needs_human_review() {
        let e = engine();
        let g = e
            .define_goal(GoalKind::Objective, "Auth typed", "harden auth", None)
            .unwrap();
        e.link_goal_to_code(
            &g.id,
            &["artifact:src/auth.rs".into()],
            CodeBindingMode::Governed,
        )
        .unwrap();
        let t = e.create_task(&g.id, "harden auth", "").unwrap();
        e.claim_task(&t.id, "agent-a", 300).unwrap();
        let claimed = e.store.get_task(&t.id).unwrap().unwrap();
        let evidence = ConformanceEvidence {
            schema_version: 1,
            task_id: Some(t.id.clone()),
            agent_id: "agent-a".into(),
            started_at: claimed.claim_started_at.unwrap(),
            ended_at: now_unix(),
            changed_node_ids: Vec::new(),
            failed_node_ids: Vec::new(),
            execution_ids: Vec::new(),
            successful_execution_ids: Vec::new(),
            commit_ids: Vec::new(),
            summary: "no activity".into(),
            provenance: Vec::new(),
        };
        let res = e.check_conformance(&evidence, Some(&t.id)).unwrap();
        assert_eq!(res.verdict, Verdict::NeedsHuman);
    }

    #[test]
    fn a_governed_documentation_binding_never_drifts_and_is_never_deleted() {
        // Goals govern code, not the shared prose every task touches. If a doc
        // (e.g. the changelog) is bound to a goal, an unrelated commit that also
        // touches it must NOT drift — the binding is ignored at read time. And,
        // crucially, nothing is deleted to achieve that: no clobber of the
        // durable intent plane.
        let e = engine();
        let g = e
            .define_goal(GoalKind::Objective, "Docs", "own the changelog", None)
            .unwrap();
        e.link_goal_to_code(
            &g.id,
            &["artifact:CHANGELOG.md".into()],
            CodeBindingMode::Governed,
        )
        .unwrap();

        let evidence = test_evidence(None, "agent-a", "artifact:CHANGELOG.md");
        let res = e.check_conformance(&evidence, None).unwrap();
        assert_eq!(res.verdict, Verdict::Aligned);

        // The binding is untouched — the fix is derived at read time, not a delete.
        assert_eq!(e.governing_goals("artifact:CHANGELOG.md").unwrap().len(), 1);
    }

    // Bug (ADR-0048): a lapsed lease silently shrank what a task could prove.
    // Re-claiming reset the evidence window to the moment of the re-claim, so
    // `validate_claim_evidence` rejected any interval reaching back past it —
    // and since the verdict is computed over whatever the evidence covers, the
    // agent's way out was to submit the surviving sliver, which passed as
    // `aligned` while the work before the lapse was never checked at all. The
    // fix admits the full interval and caps the verdict at `needs_human`,
    // because a window with a hole in it cannot certify itself.
    #[test]
    fn evidence_survives_a_lapse_but_a_holed_window_cannot_self_certify() {
        let e = engine();
        let goal = e
            .define_goal(
                GoalKind::Objective,
                "Clean delivery",
                "changes use clean design",
                None,
            )
            .unwrap();
        let node_id = "artifact:src/delivery.rs";
        e.link_goal_to_code(&goal.id, &[node_id.into()], CodeBindingMode::Governed)
            .unwrap();

        // A continuous window is the control: it still passes cleanly.
        let steady = e.create_task(&goal.id, "steady work", "no lapse").unwrap();
        e.claim_task(&steady.id, "agent-a", 300).unwrap();
        let claimed = e.store.get_task(&steady.id).unwrap().unwrap();
        let mut evidence = test_evidence(Some(steady.id.clone()), "agent-a", node_id);
        evidence.started_at = claimed.claim_started_at.unwrap();
        evidence.ended_at = now_unix();
        assert_eq!(
            e.check_conformance(&evidence, Some(&steady.id))
                .unwrap()
                .verdict,
            Verdict::Aligned
        );

        // Now the same work, interrupted: agent-b claims an hour ago on a short
        // lease, lets it lapse, and re-claims now.
        let lapsed = e
            .create_task(&goal.id, "interrupted work", "lease lapsed midway")
            .unwrap();
        let now = now_unix();
        let started = now - 3600;
        assert!(e
            .store
            .claim_task(&lapsed.id, "agent-b", 60, started)
            .unwrap());
        assert!(e.store.claim_task(&lapsed.id, "agent-b", 300, now).unwrap());

        let reclaimed = e.store.get_task(&lapsed.id).unwrap().unwrap();
        assert_eq!(reclaimed.claim_started_at, Some(started));
        assert_eq!(reclaimed.claim_lapses, 1);

        let mut spanning = test_evidence(Some(lapsed.id.clone()), "agent-b", node_id);
        spanning.started_at = started;
        spanning.ended_at = now;

        // Before the fix this call failed outright with "evidence interval falls
        // outside the live claim", which is what pushed agents to narrow the
        // span until it was accepted.
        let checked = e.check_conformance(&spanning, Some(&lapsed.id)).unwrap();
        assert_eq!(checked.verdict, Verdict::NeedsHuman);
        assert!(
            checked
                .findings
                .iter()
                .any(|finding| finding.contains("discontinuous")),
            "the receipt must name the hole, got {:?}",
            checked.findings
        );

        // ...and the cap follows the task, not the interval, so narrowing the
        // evidence no longer buys a clean pass.
        let mut narrowed = test_evidence(Some(lapsed.id.clone()), "agent-b", node_id);
        narrowed.started_at = now - 1;
        narrowed.ended_at = now;
        assert_eq!(
            e.check_conformance(&narrowed, Some(&lapsed.id))
                .unwrap()
                .verdict,
            Verdict::NeedsHuman
        );
    }

    fn test_evidence(
        task_id: Option<String>,
        agent: &str,
        changed_node_id: &str,
    ) -> ConformanceEvidence {
        ConformanceEvidence {
            schema_version: 1,
            task_id,
            agent_id: agent.into(),
            started_at: 1,
            ended_at: 2,
            changed_node_ids: vec![changed_node_id.into()],
            failed_node_ids: Vec::new(),
            execution_ids: vec!["execution:proof".into()],
            successful_execution_ids: vec!["execution:proof".into()],
            commit_ids: Vec::new(),
            summary: format!("changed {changed_node_id}"),
            provenance: vec![
                EvidenceProvenance {
                    source_id: format!("agent:{agent}"),
                    target_id: "execution:proof".into(),
                    relation: "observed".into(),
                },
                EvidenceProvenance {
                    source_id: "execution:proof".into(),
                    target_id: changed_node_id.into(),
                    relation: "modified".into(),
                },
            ],
        }
    }
}
